const item = $input.first();
const chatId = item.json.message?.chat?.id;
const voice = item.json.message?.voice;
const workflow = $getWorkflowStaticData('global');

// Detecta mensagem de voz
if (voice) {
  item.json._tipo = 'voice';
  return [item];
}

// Injeta estado salvo, se existir
if (chatId && workflow[chatId]) {
  item.json._estado = workflow[chatId];
}

return [item];

// Salva o estado e guarda o texto atual para usar depois
const chatId = $input.first().json.message.chat.id;
const workflow = $getWorkflowStaticData('global');
workflow[chatId] = 'aguardando_texto_doc';
return $input.all();

// Limpa estado e salva o texto do usuário para usar no Update
const item = $input.first();
const chatId = item.json.message.chat.id;
const texto = item.json.message.text;
const workflow = $getWorkflowStaticData('global');
delete workflow[chatId];

// Injeta o texto no item para os próximos nós usarem
item.json._texto_doc = texto;
return [item];

const data = $input.first().json;

// $input.first() já é o primeiro elemento, não precisa de [0]
const items = data?.rss?.channel?.item || [];

let mensagem = '📰 *Notícias do G1 - Mundo:*\n\n';

const total = Math.min(8, items.length);

for (let i = 0; i < total; i++) {
  const titulo = (items[i]?.title || 'Sem título').toString().trim();
  const link   = (items[i]?.link  || 'https://g1.globo.com').toString().trim();
  mensagem += `${i + 1}. [${titulo}](${link})\n\n`;
}

if (total === 0) {
  mensagem = '⚠️ Não foi possível carregar as notícias agora.';
}

return [{ json: { texto: mensagem } }];

const data = $input.first().json;

// Tenta pegar o texto transcrito em diferentes caminhos da resposta
const texto =
  data?.result?.transcription?.full_transcript ||
  data?.result?.transcription?.utterances?.map(u => u.text).join(' ') ||
  'Não foi possível transcrever o áudio.';

return [{ json: { texto } }];

// Nó único que gerencia todos os passos de texto e imagem
const item = $input.first();
const chatId = item.json.message.chat.id;
const texto = item.json.message.text;
const estado = item.json._estado;
const workflow = $getWorkflowStaticData('global');
const dados = workflow[chatId + '_c2'] || {};

let next_state, next_question;

if (texto === '/docimagem') {
  // Início: limpa dados antigos e pede nome
  workflow[chatId + '_c2'] = {};
  next_state = 'doc2_texto';
  next_question = '🖼️ *Documento com imagem*\n\nDigite o texto do documento:';
} else if (estado === 'doc2_texto') {
  dados.texto = texto;
  next_state = 'doc2_imagem';
  next_question = '✅ Texto salvo!\n\nAgora envie a *imagem* para o documento:';
}

workflow[chatId + '_c2'] = dados;
workflow[chatId] = next_state;
item.json._next_question = next_question;
return [item];

// Recebe a foto, extrai file_id e recupera dados coletados
const item = $input.first();
const chatId = item.json.message.chat.id;
const workflow = $getWorkflowStaticData('global');

// Aceita foto direta OU arquivo de imagem
const photos = item.json.message.photo;
const document = item.json.message.document;

let fileId;

if (photos && photos.length > 0) {
  // Enviado como foto — pega a maior resolução
  fileId = photos[photos.length - 1].file_id;
} else if (document && document.mime_type && document.mime_type.startsWith('image/')) {
  // Enviado como arquivo de imagem
  fileId = document.file_id;
} else {
  throw new Error('Nenhuma imagem encontrada. Envie uma foto ou imagem.');
}

const dados = workflow[chatId + '_c2'] || {};
delete workflow[chatId];
delete workflow[chatId + '_c2'];

return [{ json: { file_id: fileId, chatId, ...dados } }];

const doc = $input.first().json;
const content = doc.body.content;

let markerIndex = null;

for (const element of content) {
  if (element.paragraph) {
    for (const el of element.paragraph.elements) {
      if (el.textRun && el.textRun.content.includes('{{IMAGEM}}')) {
        markerIndex = el.startIndex;
        break;
      }
    }
  }
  if (markerIndex !== null) break;
}

if (markerIndex === null) {
  throw new Error('Marcador IMAGEM_URL não encontrado no documento.');
}

return [{ json: { 
  markerIndex,
  docId: $('Copy Template').item.json.id,
  fotoId: $('Upload Foto').item.json.id
}}];
